description:
`swap_unchecked` swaps two elements of a slice with raw pointers and is only correct for valid, different indices. Write the safe function `swap_checked(v: &mut [i32], a: usize, b: usize) -> bool` that:

- returns `false` and changes nothing if either index is out of range;
- returns `true` and changes nothing if `a == b`;
- otherwise calls `swap_unchecked` inside an `unsafe` block with a `// SAFETY:` comment, and returns `true`.

starter.solution.rs:
/// # Safety
/// `a` and `b` must be less than `v.len()` and different.
unsafe fn swap_unchecked(v: &mut [i32], a: usize, b: usize) {
    let p = v.as_mut_ptr();
    unsafe {
        let (pa, pb) = (p.add(a), p.add(b));
        let first = pa.read();
        pa.write(pb.read());
        pb.write(first);
    }
}

fn swap_checked(v: &mut [i32], a: usize, b: usize) -> bool {
    false
}

solution.solution.rs:
/// # Safety
/// `a` and `b` must be less than `v.len()` and different.
unsafe fn swap_unchecked(v: &mut [i32], a: usize, b: usize) {
    let p = v.as_mut_ptr();
    unsafe {
        let (pa, pb) = (p.add(a), p.add(b));
        let first = pa.read();
        pa.write(pb.read());
        pb.write(first);
    }
}

fn swap_checked(v: &mut [i32], a: usize, b: usize) -> bool {
    if a >= v.len() || b >= v.len() {
        return false;
    }
    if a == b {
        return true;
    }
    // SAFETY: both indices are in range and they are different.
    unsafe { swap_unchecked(v, a, b) };
    true
}

unitTests:
test("swaps", || {
    let mut v = [1, 2, 3, 4];
    check(swap_checked(&mut v, 0, 3));
    check_eq(v, [4, 2, 3, 1]);
    check(swap_checked(&mut v, 2, 2));
    check_eq(v, [4, 2, 3, 1]);
});

test("refuses bad indices", || {
    let mut v = [1, 2, 3];
    check(!swap_checked(&mut v, 0, 3));
    check(!swap_checked(&mut v, 7, 1));
    check_eq(v, [1, 2, 3]);
    let mut empty: [i32; 0] = [];
    check(!swap_checked(&mut empty, 0, 0));
});

